import { takaro, data } from '@takaro/helpers';

async function main() {
    const { pog, gameServerId, module: mod, arguments: args } = data;
    const target = args.player;
    const moduleId = mod.moduleId;
    const name = (await takaro.player.playerControllerGetOne(target.playerId)).data.data.name;
    const filters = { key: ['levelGuardBlocked'], gameServerId: [gameServerId], playerId: [target.playerId], moduleId: [moduleId] };

    for (const v of (await takaro.variable.variableControllerSearch({ filters })).data.data) {
        await takaro.variable.variableControllerDelete(v.id);
    }
    const allowed = await takaro.variable.variableControllerSearch({ filters: { ...filters, key: ['levelGuardAllowed'] } });
    if (!allowed.data.data.length) {
        await takaro.variable.variableControllerCreate({
            key: 'levelGuardAllowed',
            value: JSON.stringify({ by: pog.playerId, at: new Date().toISOString() }),
            gameServerId,
            playerId: target.playerId,
            moduleId,
        });
    }
    await pog.pm(`${name} can join now; the level guard skips them from here on.`);
}

await main();

