import { takaro, data } from '@takaro/helpers';

async function main() {
    const { player, pog, gameServerId, module: mod } = data;
    const cfg = mod.userConfig;
    const moduleId = mod.moduleId;
    const byKey = (key) => ({ filters: { key: [key], gameServerId: [gameServerId], playerId: [player.id], moduleId: [moduleId] } });

    // An admin let this player in with levelallow
    if ((await takaro.variable.variableControllerSearch(byKey('levelGuardAllowed'))).data.data.length) return;

    const blocked = (await takaro.variable.variableControllerSearch(byKey('levelGuardBlocked'))).data.data[0];
    const isNew = Date.now() - new Date(pog.createdAt).getTime() < (cfg.newPlayerMinutes ?? 60) * 60000;
    if (!blocked && !isNew) return;

    // Limit: average of the 3 highest regular-player levels saved by UpdateLevelLimit, else the configured level
    let maxLevel = cfg.maxLevel ?? 25;
    let source = 'configured';
    if (cfg.autoLimit !== false) {
        const auto = (
            await takaro.variable.variableControllerSearch({ filters: { key: ['levelGuardLimit'], gameServerId: [gameServerId], moduleId: [moduleId] } })
        ).data.data.find((v) => !v.playerId);
        if (auto) {
            const a = JSON.parse(auto.value);
            maxLevel = a.limit;
            source = `average of the top regulars ${a.top.join('/')}`;
        }
    }

    // The connector reads the level once the character has spawned; this hook runs after the hook delay (15 s)
    let level = null;
    for (let i = 0; i < 6 && level === null; i++) {
        const res = (await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, { command: `level ${pog.gameId}` })).data.data;
        const raw = res.rawResult || '';
        const m = /: level (\d+)/.exec(raw);
        if (m) level = Number(m[1]);
        else if (/not online/.test(raw)) return;
        else await new Promise((r) => setTimeout(r, 5000));
    }

    if (level === null && !blocked) {
        console.log(`level of ${player.name} could not be read; not checked`);
        return;
    }
    if (level !== null && level <= maxLevel) {
        // A blocked player who comes back with a character within the limit gets in, and the block ends
        if (blocked) {
            await takaro.variable.variableControllerDelete(blocked.id);
            console.log(`${player.name} was blocked and joined with a level ${level} character (limit ${maxLevel}); block removed`);
        } else {
            console.log(`${player.name} level ${level} is within ${maxLevel} (${source})`);
        }
        return;
    }

    const reason = (cfg.kickReason || 'New players are limited to level {max}.').replace('{max}', String(maxLevel));
    await takaro.gameserver.gameServerControllerKickPlayer(gameServerId, player.id, { reason });

    if (blocked) {
        console.log(`${player.name} is blocked by the level guard and was kicked again`);
        return;
    }
    await takaro.variable.variableControllerCreate({
        key: 'levelGuardBlocked',
        value: JSON.stringify({ level, maxLevel, source, at: new Date().toISOString() }),
        gameServerId,
        playerId: player.id,
        moduleId,
    });

    if (cfg.discordChannelId) {
        const prefix = (await takaro.settings.settingsControllerGetOne('commandPrefix', gameServerId)).data.data.value;
        const ping = cfg.discordRoleId ? `<@&${cfg.discordRoleId}> ` : '';
        await takaro.discord.discordControllerSendMessage(cfg.discordChannelId, {
            message: `${ping}**${player.name}** was kicked: first time on the server with a level ${level} character (limit ${maxLevel}, ${source}). They get in with a character at or below the limit, or use \`${prefix}levelallow ${player.name}\` in game to let them in.`,
        });
    }
}

await main();

