import { takaro, data } from '@takaro/helpers';

async function main() {
    const { gameServerId, module: mod } = data;
    const cfg = mod.userConfig;
    if (cfg.autoLimit === false) return;
    const moduleId = mod.moduleId;
    const floor = cfg.maxLevel ?? 25;
    const newMs = (cfg.newPlayerMinutes ?? 60) * 60000;
    const vars = async (key, playerId) =>
        (
            await takaro.variable.variableControllerSearch({
                filters: { key: [key], gameServerId: [gameServerId], moduleId: [moduleId], ...(playerId ? { playerId: [playerId] } : {}) },
                limit: 1000,
            })
        ).data.data;

    // 1. Remember the highest level seen of every regular online. Not counted: new players, players the guard
    //    kicked (blocked), and players an admin let in above the limit with levelallow.
    const raw = (await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, { command: 'levels' })).data.data.rawResult || '';
    for (const m of raw.matchAll(/\((\d+)\): level (\d+)/g)) {
        const gameId = m[1];
        const level = Number(m[2]);
        const pog = (await takaro.playerOnGameserver.playerOnGameServerControllerSearch({ filters: { gameId: [gameId], gameServerId: [gameServerId] } })).data.data[0];
        if (!pog || Date.now() - new Date(pog.createdAt).getTime() < newMs) continue;
        if ((await vars('levelGuardBlocked', pog.playerId)).length) continue;
        if ((await vars('levelGuardAllowed', pog.playerId)).length) continue;
        const seen = (await vars('levelGuardLevel', pog.playerId))[0];
        if (!seen) {
            await takaro.variable.variableControllerCreate({ key: 'levelGuardLevel', value: String(level), gameServerId, playerId: pog.playerId, moduleId });
        } else if (level > Number(seen.value)) {
            await takaro.variable.variableControllerUpdate(seen.id, { value: String(level) });
        }
    }

    // 2. Limit = average of the three highest levels saved, never below the configured level
    const saved = (await vars('levelGuardLevel')).map((v) => Number(v.value)).filter((l) => l > 0).sort((a, b) => b - a);
    if (!saved.length) {
        console.log('no regular player levels saved yet; limit unchanged');
        return;
    }
    const top = saved.slice(0, 3);
    const limit = Math.max(floor, Math.round(top.reduce((s, l) => s + l, 0) / top.length));
    const value = JSON.stringify({ limit, top, at: new Date().toISOString() });
    const existing = (await vars('levelGuardLimit')).find((v) => !v.playerId);
    if (existing) await takaro.variable.variableControllerUpdate(existing.id, { value });
    else await takaro.variable.variableControllerCreate({ key: 'levelGuardLimit', value, gameServerId, moduleId });
    console.log(`level limit for new players: ${limit} (top saved levels ${top.join(', ')}, floor ${floor})`);
}

await main();
